SELECT CAST(date_format(process_date,'yyyyMMdd') AS long) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,source_path ,filter_error ,filter_error_msg ,type_error ,type_error_msg ,mapping_error ,mapping_error_msg ,CASE WHEN status IS NULL AND rn = 1 AND mapping_error = '' THEN 'MAP' WHEN status IS NULL AND rn = 1 AND mapping_error <> '' THEN 'UNMAP' WHEN status IS NULL AND rn <> 1 THEN 'DUP' ELSE status END AS status ,filter_dtm , b_no,create_by ,process_date,workflow_process_date,to_timestamp(file_date,'yyyyMMddHHmmss') as file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,source_path ,replace(filter_error,' is NULL','') filter_error ,filter_error filter_error_msg ,regexp_replace(type_error,': Invalid [A-Z]+ type \\(Raw=[\\S]*\\)','') type_error ,type_error type_error_msg ,replace(mapping_error,' is NULL','') mapping_error ,mapping_error mapping_error_msg ,status ,filter_dtm , b_no,get_user() AS create_by ,now() AS process_date ,CASE WHEN status IS NOT NULL THEN -99 ELSE ROW_NUMBER() over(PARTITION BY chk_duplicate,status ORDER BY file_date) END AS rn , workflow_process_date,file_date FROM ( SELECT raw.cdr_id ,raw.cdr_type ,raw.partner ,raw.owner ,raw.iccid ,raw.first_installed ,raw.profile_type ,raw.eid ,raw.sim_type ,mapping.cp_id ,mapping.service_id ,mapping.price_rate_type ,mapping.network_type ,mapping.invoicing_company_id AS invoicing_co_id ,mapping.share_basis ,raw.cdr_filename ,raw.chk_duplicate ,raw.filter_dtm, raw.b_no ,cdr_mas.source_path ,concat( CASE WHEN mapping.cp_id is null THEN 'cp_id is NULL|' else '' end ,CASE WHEN mapping.service_id is null THEN 'service_id is NULL|' else '' end ,CASE WHEN mapping.network_type is null THEN 'network_type is NULL|' else '' end ,CASE WHEN mapping.invoicing_company_id is null THEN 'invoicing_company_id is NULL|' else '' end ,CASE WHEN mapping.share_basis is null THEN 'share_basis is NULL|' else '' end ) AS mapping_error ,filter_error ,type_error ,CASE WHEN filter_error <> '' THEN 'MAN' WHEN type_error <> '' THEN 'TYP' WHEN dup.chk_duplicate is not null THEN 'DUP' ELSE NULL END AS status ,file_date,workflow_process_date  FROM ( SELECT concat(date_format(now(),'yyyyMMddHHmmss'),format_string('%03d',1),format_string('%09d',ROW_NUMBER() over(order by 1))) AS cdr_id ,partner ,owner ,iccid ,to_timestamp(left(first_installed,14),'yyyyMMddHHmmss') first_installed ,profile_type ,eid ,sim_type ,'1' cdr_type ,input_source_name AS cdr_filename ,chk_duplicate ,filter_dtm ,b_no ,concat( CASE WHEN partner is null THEN 'partner is NULL|' else '' end ,CASE WHEN owner is null THEN 'owner is NULL|' else '' end ,CASE WHEN iccid is null THEN 'iccid is NULL|' else '' end ,CASE WHEN first_installed is null THEN 'first_installed is NULL|' else '' end ,CASE WHEN profile_type is null THEN 'profile_type is NULL|' else '' end ,CASE WHEN sim_type is null THEN 'sim_type is NULL|' else '' end ) AS filter_error ,concat( CASE WHEN to_timestamp(left(first_installed,14),'yyyyMMddHHmmss') is null THEN concat('first_installed: Invalid TIMESTAMP type (Raw=',coalesce(first_installed,''),')|') else '' end ) AS type_error ,file_date FROM ( SELECT nullif(partner,'') partner ,nullif(owner,'') owner ,nullif(iccid,'') iccid ,nullif(first_installed,'') first_installed ,nullif(profile_type,'') profile_type ,nullif(eid,'') eid ,nullif(sim_type,'') sim_type ,process_date AS filter_dtm ,concat(partner,'_ESIM_',sim_type) AS b_no ,replace(regexp_extract(reverse(split(input_source_name,'/'))[0],'(.+)([_])(\\d{8}[_]\\d{6})([_])(.+[.].+)',3),'_','') AS file_date ,input_source_name ,coalesce(iccid,'') AS chk_duplicate FROM tb_landing_ss_esim WHERE  body_tag='02' and partition_minute BETWEEN ( SELECT MIN(checkpoint_partition) FROM tb_staging_ss_esim_checkpoint_temp) AND ( SELECT MAX(checkpoint_partition) FROM tb_staging_ss_esim_checkpoint_temp) AND partition_minute > ( SELECT coalesce(MAX(checkpoint_partition),0) FROM tb_staging_ss_esim_checkpoint) ) ) raw CROSS JOIN ( SELECT workflow_process_date FROM tb_staging_ss_esim_landing_to_discovery_workflow_status ) JOIN ( SELECT cdr_type ,source_path FROM ext_dss_tb_master_cdr_type WHERE record_status = 'A' ) cdr_mas ON raw.cdr_type = cdr_mas.cdr_type LEFT JOIN ( SELECT chk_duplicate FROM tb_transaction_ss_esim_valid UNION SELECT chk_duplicate FROM tb_transaction_ss_esim_temp ) dup ON raw.chk_duplicate = dup.chk_duplicate LEFT JOIN ( SELECT distinct nullif(b_no,'') AS b_no ,nullif(content_partner_id,'') AS cp_id ,nullif(service_id,'') AS service_id ,nullif(network_type,'') AS network_type ,nullif(share_basis,'') AS share_basis ,nullif(invoicing_company_id,'') AS invoicing_company_id ,to_date(effective_date) AS effective_date ,to_date(expired_date) AS expired_date ,nullif(price_rate_type,'') AS price_rate_type FROM ext_dss_vw_service_mapping_bno_key WHERE record_status = 'A' AND b_no like '%\_ESIM\_%' ) mapping ON raw.b_no = mapping.b_no AND raw.owner = mapping.invoicing_company_id AND mapping.effective_date <= to_date(raw.first_installed) AND (mapping.expired_date is null or mapping.expired_date >= to_date(raw.first_installed)) ) )